#!/usr/bin/env python3
from pathlib import Path
from bs4 import BeautifulSoup
import json, re

ROOT=Path(__file__).resolve().parents[1]
DIST=ROOT/'dist'
RELEASE='FR-NAV1.29.0-HF3.10'
BASE='FR-NAV1.28.0-HF3.9'

PAGES=[
 'member-profile-preview/index.html','membership-start/index.html','business-dashboard/index.html',
 'local-growth-engine/index.html','navigator-growth-desk/index.html','claim-profile/index.html'
]

def soup_for(rel):
    return BeautifulSoup((DIST/rel).read_text(encoding='utf-8'),'html.parser')

def ensure_release_assets(soup, body_class):
    meta=soup.find('meta',attrs={'name':'franklin-release'})
    if meta: meta['content']=RELEASE
    else:
        meta=soup.new_tag('meta'); meta['name']='franklin-release'; meta['content']=RELEASE; soup.head.append(meta)
    if not soup.find('link',href=re.compile(r'/assets/hf310\.css')):
        link=soup.new_tag('link',rel='stylesheet',href='/assets/hf310.css?v=frnav1290'); soup.head.append(link)
    body=soup.body
    classes=list(body.get('class',[]));
    for c in ['hf310',body_class]:
        if c not in classes: classes.append(c)
    body['class']=classes
    if not soup.find('script',src=re.compile(r'/assets/hf310\.js')):
        sc=soup.new_tag('script',src='/assets/hf310.js?v=frnav1290',defer=True); body.append(sc)

def replace_main(soup, html):
    old=soup.find('main')
    frag=BeautifulSoup(html,'html.parser')
    new=frag.find('main')
    old.replace_with(new)

def save(rel,soup):
    (DIST/rel).write_text(str(soup)+'\n',encoding='utf-8')

