# --- Growth guide catalog: preserve all 13 guide routes, simplify catalog ---
s=soup_for('navigator-growth-desk/index.html'); ensure_release_assets(s,'hf310-growth-guides')
old_cards=s.select('.growth-playbook-card')
clean=[]
for card in old_cards:
    eye=card.select_one('.eyebrow')
    subtitle=eye.get_text(' ',strip=True) if eye else ''
    if eye: eye.decompose()
    link=card.find('a')
    if link: link.string='Open guide'; link['class']=['hf310-guide-link']
    h=card.find('h3')
    if h:
        short=re.sub(r'\s+business guide$','',h.get_text(' ',strip=True),flags=re.I)
        short=re.sub(r'\s+participation guide$','',short,flags=re.I)
        h.string=short
    if subtitle:
        p=card.find('p')
        if p:
            p['data-guide-audience']='true'
    card['class']=['card','growth-playbook-card','hf310-guide-card']
    clean.append(str(card))
all_cards=''.join(clean)
