hf310_css=r'''/* FR-NAV1.29.0-HF3.10 — owner-review business/profile tools finishing */
.hf310-compact-hero{padding-block:54px 42px}.hf310-compact-hero h1{max-width:850px}.hf310-compact-hero .r29-lead{max-width:800px}.hf310-checks{margin:.75rem 0 0;padding-left:1.2rem}.hf310-checks li{margin:.42rem 0}.hf310-preview-compare{padding-block:36px}.hf310-profile-context{display:flex;gap:8px 18px;align-items:baseline;flex-wrap:wrap;margin-bottom:18px;color:#44545a}.hf310-profile-context strong{color:var(--ink)}.hf310-preview-layout{align-items:start}.hf310-preview-form{padding:20px}.hf310-readiness{margin-bottom:14px}.hf310-editor-section{border-top:1px solid var(--line);padding:0}.hf310-editor-section:first-of-type{border-top:0}.hf310-editor-section>summary{font-weight:800;padding:16px 2px;color:var(--brand-dark)}.hf310-editor-body{padding:0 0 15px}.hf310-photo-check{display:flex!important;align-items:flex-start;gap:10px;margin:5px 0!important}.hf310-photo-check input{width:auto!important;flex:0 0 auto;margin-top:.3rem}.hf310-rich-preview{position:sticky;top:98px;min-height:480px}.hf310-rich-preview .hf310-preview-head{display:flex;align-items:center;gap:14px}.hf310-rich-preview .hf310-preview-actions{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.hf310-rich-preview .hf310-preview-actions span{border:1px solid #b9cbcc;border-radius:7px;padding:7px 10px;font-weight:750}.hf310-preview-section{border-top:1px solid var(--line);padding-top:16px;margin-top:16px}.hf310-preview-section h3{margin:0 0 7px}.hf310-preview-section p{margin:.25rem 0}.hf310-preview-muted{color:#68767a;font-style:italic}.hf310-online-list{display:flex;gap:8px;flex-wrap:wrap}.hf310-online-list span{background:var(--soft);border:1px solid #cee0de;border-radius:6px;padding:5px 8px}.hf310-gallery-placeholder{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.hf310-gallery-placeholder span{height:70px;border-radius:8px;background:linear-gradient(135deg,#eaf5f2,#f8f3e8);border:1px solid #d7e3e2}.hf310-compact-price,.hf310-membership-decision{padding-block:38px}.hf310-member-example{display:flex;align-items:center;gap:14px;margin-top:22px;padding:18px;border:1px solid #bfd5d3;border-radius:14px;background:#fff}.hf310-example-mark{width:52px;height:52px;border-radius:12px;background:var(--brand-dark);color:#fff;display:grid;place-items:center;font-weight:900}.hf310-member-example>div:nth-child(2){display:grid;gap:3px;flex:1}.hf310-member-example span{color:#516167}.hf310-example-actions{display:flex!important;gap:7px}.hf310-example-actions span{border:1px solid #b5c8c8;border-radius:6px;padding:5px 8px;color:var(--brand-dark)}.hf310-decision-card,.hf310-dashboard-card{max-width:760px;margin:auto}.hf310-always-free{max-width:950px;margin:18px auto 0}.hf310-policy,.hf310-free-strip,.hf310-free-tools{padding-block:30px}.hf310-path-section{padding-block:34px}.hf310-path{display:flex;align-items:center;gap:10px 16px;flex-wrap:wrap;font-weight:800}.hf310-path>span:not([aria-hidden]){border:1px solid #cddddd;background:#fff;border-radius:9px;padding:9px 12px}.hf310-path strong{display:inline-grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--brand-dark);color:#fff;margin-right:7px}.hf310-path-note{margin:.7rem 0 0;color:#536268}.hf310-selected-business{margin-top:12px;padding:10px 12px;border-left:3px solid var(--brand);background:var(--soft)}
.hf310-growth-workspace{padding-top:40px}.hf310-growth-form fieldset{margin-bottom:16px}.hf310-plan-output .hf310-result-section{display:none}.hf310-plan-output.is-ready .hf310-result-section{display:block}.hf310-plan-output:not(.is-ready) [data-growth-status]{margin-top:18px}.hf310-growth-followup{padding-block:32px}.hf310-planner-details{margin-top:18px;border-top:1px solid var(--line);padding-top:12px}.hf310-planner-details summary{font-weight:800;color:var(--brand-dark)}.hf310-runtime-only{display:none!important}.hf310-optional-idea{border-top:1px solid var(--line);margin-top:16px;padding-top:14px}.hf310-optional-idea:empty{display:none}.hf310-optional-idea strong{display:block;margin-bottom:5px}.hf310-growth-guides .hero{padding-bottom:42px}.hf310-recommended-guide{padding-block:34px}.hf310-guide-recommendation{border:1px solid #c5d9d7;background:var(--soft);border-radius:12px;padding:18px;margin-top:10px}.hf310-guide-recommendation h2{margin:.2rem 0 .5rem}.hf310-guide-browser>summary{font-size:1.25rem;font-weight:850;padding:14px 0}.hf310-guide-grid{grid-template-columns:repeat(3,minmax(0,1fr));margin-top:16px}.hf310-guide-card{padding:17px}.hf310-guide-card h3{font-size:1.02rem}.hf310-guide-card p{font-size:.94rem}.hf310-guide-link{font-weight:800}.hf310-guide-purpose{margin-top:20px;padding:14px 16px;background:var(--soft);border-radius:10px}.hf310-guide-planner{padding-block:36px}.hf310-claim-results{display:grid;gap:8px;margin-top:12px}.hf310-claim-result{display:flex;width:100%;text-align:left;justify-content:space-between;gap:14px;align-items:center;border:1px solid #c5d4d4;border-radius:9px;background:#fff;padding:11px 13px;color:var(--ink);cursor:pointer}.hf310-claim-result strong,.hf310-claim-result span{display:block}.hf310-claim-result small{display:block;color:#59676c}.hf310-selected-profile-section{padding-block:38px}.hf310-selected-profile{border:1px solid #c7d8d7;background:var(--soft);border-radius:12px;padding:16px;margin:12px 0 18px}.hf310-selected-profile h2{margin:.1rem 0}.hf310-profile-actions{display:flex;gap:10px;flex-wrap:wrap}.hf310-claim-note{padding-block:26px}.hf310-claim-note p{margin:0}
@media(max-width:900px){.hf310-guide-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.hf310-rich-preview{position:static}.hf310-example-actions{display:none!important}}@media(max-width:640px){.hf310-guide-grid{grid-template-columns:1fr}.hf310-member-example{align-items:flex-start}.hf310-path{display:grid;grid-template-columns:1fr}.hf310-path>span[aria-hidden]{display:none}.hf310-profile-actions .button{width:100%}}
'''
(DIST/'assets/hf310.css').write_text(hf310_css+'\n',encoding='utf-8')

# --- Shared HF3.10 JS ---
hf310_js=r'''/* FR-NAV1.29.0-HF3.10 — profile-aware business tools, richer preview, single profile search */
(()=>{'use strict';
const API='https://franklin-navigator-membership.onrender.com';
const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
async function api(path){const r=await fetch(API+path,{credentials:'include'});if(!r.ok)throw new Error(String(r.status));return r.json()}
let profileRows=null;
async function loadProfiles(){if(profileRows)return profileRows;const m=await fetch('/data/franklin-profiles-manifest.json').then(r=>r.json());const chunks=await Promise.all(m.chunks.map(c=>fetch(c.file).then(r=>r.json())));profileRows=chunks.flatMap(c=>c.records).map(r=>({...r,_s:`${r.n||''} ${r.c||''} ${r.g||''} ${r.l||''}`.toLowerCase()}));return profileRows}
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function urlLabel(name,value){return value?`<span>${esc(name)}</span>`:''}
async function publicProfileFacts(id){const html=await fetch('/profiles/'+encodeURIComponent(id)+'/').then(r=>r.text());const d=new DOMParser().parseFromString(html,'text/html');const facts={name:q('h1',d)?.textContent?.trim()||'',category:q('.r22-profile-hero .eyebrow',d)?.textContent?.trim()||'',city:q('.profile-location',d)?.textContent?.trim()||''};qa('.profile-primary-actions a',d).forEach(a=>{const href=a.getAttribute('href')||'',t=(a.textContent||'').toLowerCase();if(/^tel:/.test(href))facts.phone=href.replace(/^tel:/,'');else if(/^mailto:/.test(href))facts.email=href.replace(/^mailto:/,'');else if(t.includes('website')||/^https?:/.test(href))facts.website=href});return facts}
function memberPreview(){const form=q('.hf310-preview-form'),preview=q('[data-r28-preview]');if(!form||!preview)return;const v=n=>String(form.elements[n]?.type==='checkbox'?(form.elements[n]?.checked?'yes':''):form.elements[n]?.value||'').trim();const set=(n,val)=>{if(form.elements[n]&&val&&!form.elements[n].value)form.elements[n].value=val};
 const render=()=>{const name=v('name')||'Your business',category=v('category')||'Business category',city=v('city')||'Franklin area',initials=name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()||'FN';const services=v('services').split(',').map(x=>x.trim()).filter(Boolean).slice(0,8);const actions=[['Website',v('website')],['Call',v('phone')],['Email',v('email')],['Book',v('booking')],['Quote / contact',v('quote')],['Order / menu',v('order')],['Directions',v('directions')]].filter(x=>x[1]);const online=[['LinkedIn',v('linkedin')],['Facebook',v('facebook')],['Instagram',v('instagram')],['Official link',v('online')]].filter(x=>x[1]);preview.innerHTML=`<div class="hf310-preview-head"><div class="r28-preview-mark" aria-hidden="true">${esc(initials)}</div><div><div class="eyebrow">Community Member preview</div><h2>${esc(name)}</h2><p class="r28-preview-meta">${esc(category)} · ${esc(city)}</p></div></div><div class="hf310-preview-actions">${actions.map(([x])=>`<span>${esc(x)}</span>`).join('')||'<span>Verified actions appear here</span>'}</div><section class="hf310-preview-section"><h3>About</h3><p class="${v('about')?'':'hf310-preview-muted'}">${esc(v('about')||'Add a reviewed About description to show what makes your business useful locally.')}</p></section><section class="hf310-preview-section"><h3>Services</h3>${services.length?`<div class="r28-chip-row">${services.map(x=>`<span class="r28-chip">${esc(x)}</span>`).join('')}</div>`:'<p class="hf310-preview-muted">Add services or participation areas.</p>'}</section><section class="hf310-preview-section"><h3>Hours & practical details</h3><p>${esc(v('hours')||'Hours can appear here when supplied and reviewed.')}</p><p>${esc(v('languages')||'Languages and accessibility information can appear here.')}</p></section><section class="hf310-preview-section"><h3>Official online presence</h3><div class="hf310-online-list">${online.map(([x])=>`<span>${esc(x)}</span>`).join('')||'<span>Verified social and official links</span>'}</div></section>${v('photos')?'<section class="hf310-preview-section"><h3>Photos & gallery</h3><div class="hf310-gallery-placeholder"><span></span><span></span><span></span></div></section>':''}<p class="fine-print">Preview only. Nothing is published by this form. Membership does not imply endorsement or ranking.</p>`};
 form.addEventListener('input',render);form.addEventListener('change',render);render();
 const id=new URLSearchParams(location.search).get('profile');if(id){Promise.all([loadProfiles(),publicProfileFacts(id)]).then(([rows,f])=>{const row=rows.find(r=>r.i===id)||{};set('name',f.name||row.n);set('category',f.category||row.c);set('city',f.city||row.l||row.g);set('phone',f.phone);set('email',f.email);set('website',f.website);if(form.elements.category&&form.elements.category.value){form.elements.category.readOnly=true;q('[data-hf310-category-help]')?.classList.add('is-canonical')}const ctx=q('[data-hf310-profile-context]');if(ctx){ctx.innerHTML=`<strong>${esc(f.name||row.n||'Selected profile')}</strong><span>Existing public facts are prefilled below. Add only information you want to preview or propose for review.</span>`}form.dispatchEvent(new Event('input',{bubbles:true}))}).catch(()=>{})}}
function membershipState(){const cta=q('[data-hf310-membership-cta]');if(!cta)return;(async()=>{try{await api('/api/accounts/me');const list=await api('/api/member/profiles');const p=Array.isArray(list.profiles)&&list.profiles[0];if(!p)return;let pub={};try{pub=await api('/api/member/public-profile?profileId='+encodeURIComponent(p.profile_id))}catch(_){}if(pub.activePaidMember){cta.textContent='Manage membership';cta.href='/membership-status/'}else{cta.textContent='Join Community Membership — $35/year';cta.href='/membership-enroll/?profile='+encodeURIComponent(p.profile_id)}}catch(_){}})()}
function businessName(){const heading=q('[data-hf310-business-heading]'),box=q('[data-hf310-selected-business]');if(!heading||!box)return;(async()=>{try{await api('/api/accounts/me');const list=await api('/api/member/profiles');const p=Array.isArray(list.profiles)&&list.profiles[0];if(!p)return;heading.textContent='Manage and improve '+p.name+'.';box.hidden=false;box.innerHTML=`<strong>${esc(p.name)}</strong> · <a href="/profiles/${encodeURIComponent(p.profile_id)}/">View public profile</a>`}catch(_){}})()}
function growthPlanner(){const root=q('[data-local-growth-engine]'),form=q('[data-growth-onboarding]'),out=q('[data-hf310-plan-output]'),hiddenDraft=q('[data-growth-drafts]'),idea=q('[data-hf310-idea]');if(!root||!form||!out)return;const ready=()=>{out.classList.add('is-ready');setTimeout(()=>{const first=q('.growth-draft',hiddenDraft);if(first&&idea){const p=q('p',first);idea.innerHTML=p?`<strong>Optional message / promotion idea</strong><p>${esc(p.textContent)}</p>`:''}},0)};form.addEventListener('submit',()=>setTimeout(ready,0));form.addEventListener('reset',()=>{out.classList.remove('is-ready');if(idea)idea.replaceChildren()})}
const guideMap=[[/legal|attorney|law/i,['Legal services','/navigator-growth-desk/legal/']],[/health|clinic|medical|care|dent/i,['Health services','/navigator-growth-desk/health/']],[/home|contract|real estate|property|plumb|roof|electric/i,['Home & property services','/navigator-growth-desk/home-property/']],[/auto|vehicle|dealer|towing|collision/i,['Auto services','/navigator-growth-desk/auto/']],[/restaurant|cafe|food|hospitality|venue/i,['Restaurant & hospitality','/navigator-growth-desk/restaurants-hospitality/']],[/retail|shop|store/i,['Retail & local shopping','/navigator-growth-desk/retail/']],[/account|tax|bookkeep/i,['Accounting & tax','/navigator-growth-desk/accounting-tax/']],[/education|tutor|school|learning/i,['Education & tutoring','/navigator-growth-desk/education-tutoring/']],[/senior|caregiver/i,['Senior & caregiver services','/navigator-growth-desk/senior-services/']],[/beauty|salon|fitness|wellness|barber/i,['Beauty, fitness & wellness','/navigator-growth-desk/beauty-fitness/']],[/pet|animal|veterinar|groom/i,['Pet & animal services','/navigator-growth-desk/pet-services/']],[/nonprofit|community|faith|civic/i,['Community organization','/navigator-growth-desk/community-nonprofit/']]];
function growthGuideRecommendation(){const box=q('[data-hf310-guide-recommendation]');if(!box)return;(async()=>{try{await api('/api/accounts/me');const list=await api('/api/member/profiles');const p=Array.isArray(list.profiles)&&list.profiles[0];if(!p)return;const facts=await publicProfileFacts(p.profile_id);const text=facts.category+' '+p.name;const hit=guideMap.find(([rx])=>rx.test(text))||[[''],['Professional services','/navigator-growth-desk/professional-services/']][1];const label=Array.isArray(hit)?hit[1][0]:hit[0];const href=Array.isArray(hit)?hit[1][1]:'/navigator-growth-desk/professional-services/';box.innerHTML=`<h2>${esc(p.name)}</h2><p>Recommended guide: <strong>${esc(label)}</strong></p><a class="button primary" href="${href}">Open recommended guide</a>`}catch(_){}})()}
function claimSearch(){const form=q('[data-hf310-claim-search-form]'),input=q('#hf310-profile-q'),results=q('[data-hf310-claim-results]'),section=q('[data-hf310-claim-selected]'),profile=q('[data-hf310-selected-profile]'),actions=q('[data-hf310-profile-actions]');if(!form||!input||!results)return;let timer;const showSelected=row=>{results.replaceChildren();section.hidden=false;profile.innerHTML=`<h2>${esc(row.n)}</h2><p>${esc([row.c,row.l||row.g].filter(Boolean).join(' · '))}</p><a href="/profiles/${encodeURIComponent(row.i)}/">Open public profile</a>`;const profileUrl=location.origin+'/profiles/'+row.i+'/';actions.innerHTML=`<a class="button primary" href="/membership-enroll/?profile=${encodeURIComponent(row.i)}">Manage this profile</a><a class="button" href="/corrections/?listing=${encodeURIComponent(row.n)}&profile=${encodeURIComponent(row.i)}&url=${encodeURIComponent(profileUrl)}">Correct information</a><a class="button" href="/corrections/?action=PUBLIC_REMOVAL&profile=${encodeURIComponent(row.i)}&url=${encodeURIComponent(profileUrl)}">Request removal</a><a class="button" href="/member-profile-preview/?profile=${encodeURIComponent(row.i)}">Preview member profile</a>`;section.scrollIntoView({behavior:'smooth',block:'start'})};const run=async()=>{const needle=input.value.trim().toLowerCase();if(needle.length<2){results.replaceChildren();return}try{const rows=(await loadProfiles()).filter(r=>r._s.includes(needle)).slice(0,8);results.replaceChildren();if(!rows.length){results.textContent='No matching profile found. Try another name or request a free basic public profile.';return}rows.forEach(row=>{const b=document.createElement('button');b.type='button';b.className='hf310-claim-result';b.innerHTML=`<span><strong>${esc(row.n)}</strong><small>${esc([row.c,row.l||row.g].filter(Boolean).join(' · '))}</small></span><span>Choose</span>`;b.addEventListener('click',()=>showSelected(row));results.append(b)})}catch(_){results.textContent='Profile search could not load. You can still use Search profiles to open Find Local.'}};form.addEventListener('submit',e=>{e.preventDefault();run()});input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(run,180)});const pre=new URLSearchParams(location.search).get('profile');if(pre)loadProfiles().then(rows=>{const row=rows.find(r=>r.i===pre);if(row)showSelected(row)}).catch(()=>{})}
function disclosureArrows(){qa('details>summary').forEach(s=>{s.textContent=s.textContent.replace(/\s*\+\s*$/,'').trim()})}
document.addEventListener('DOMContentLoaded',()=>{memberPreview();membershipState();businessName();growthPlanner();growthGuideRecommendation();claimSearch();disclosureArrows()});
})();
'''
(DIST/'assets/hf310.js').write_text(hf310_js+'\n',encoding='utf-8')

# Site-wide contrast hardening: explicit, readable button colors. This is intentionally narrow to button-like controls.
access=DIST/'assets/accessibility.css'
text=access.read_text(encoding='utf-8')
contrast='''\n/* HF3.10 site-wide button contrast hardening */\na.button:not(.primary),button.button:not(.primary){color:#03454b!important;background:#fff!important;border-color:#03454b!important}\na.button:not(.primary):hover,button.button:not(.primary):hover{color:#03454b!important;background:#f3f8f7!important}\na.button.primary,button.button.primary{color:#fff!important;background:#03454b!important;border-color:#03454b!important}\na.button.primary:hover,button.button.primary:hover{color:#fff!important;background:#075f66!important;border-color:#075f66!important}\n'''
if 'HF3.10 site-wide button contrast hardening' not in text:
    access.write_text(text.rstrip()+contrast+'\n',encoding='utf-8')

# Release marker and improvement list.
release={
 'release':RELEASE,'date':'2026-09-12','base':BASE,
 'scope':'Owner-reviewed business/member journey finishing: profile-aware preview, membership conversion simplification, state-aware business dashboard, compact growth planner/guides, single profile-search flow and site-wide button contrast hardening',
 'counts':{'profiles':19103},
 'authority':{'profileFacts':'UNCHANGED_PROFILE_FACTORY_AUTHORITY_PRESERVED','pf15_21':'DEFER_WITH_CAUSE','li31':'DEFER_WITH_CAUSE','smarterJustice':'NOT_USED'},
 'preserved':['Sports static-first and no-JS usefulness','Directory membership-neutral ordinary ranking','public profile direct contact actions','free factual corrections and removal','active-member Similar local profiles suppression','member publication review/provenance/representation gates','Community Membership $35/year','privacy and no-public-rating boundaries']
}
(ROOT/'PRODUCTION_RELEASE.json').write_text(json.dumps(release,indent=2)+'\n',encoding='utf-8')
(ROOT/'NEXT_VERSION_IMPROVEMENT_LIST__FR_NAV1_29_0_HF310.md').write_text('''# Next Version Improvement List — FR-NAV1.29.0-HF3.10\n\n1. Continue live owner review at laptop and mobile sizes after deployment.\n2. Improve profile-aware prefill only when accepted public facts are available; never make member input authoritative without review.\n3. Continue verified link enrichment from accepted Profile Factory handoffs without inventing or exposing empty actions.\n4. Keep business tools short: show the next applicable step first and deeper tools on demand.\n5. Continue contrast/accessibility regression checks on every material release.\n6. Keep Today/Activities currentness gates and Sports static-first regressions green.\n7. Do not change $35/year membership, free corrections/removal, or membership-neutral Directory ranking without explicit owner authorization.\n''',encoding='utf-8')

print(json.dumps({'release':RELEASE,'base':BASE,'changedPages':PAGES,'status':'BUILT_PENDING_QUALIFICATION'},indent=2))
